INSERT INTO `sys_active_center` (`id`, `name`, `start_date`, `end_date`, `picture`, `details`, `target_amount`, `status`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`) VALUES (6, '20250224为期一个月的活动', '2025-03-24', '2026-03-01', 'https://ai-cloud-system.tos-cn-beijing.volces.com/2025/03/29/9df2c83755e4437181a107e49ce1b15d.jpg', '<h3 style=\"text-align: start; line-height: 1.5;\"><strong>逸雲数智试营业全球首发</strong></h3><p style=\"text-align: start;\"><strong>「智联无界 未来加速」—— AGI网络基座限时抢购计划</strong><br><strong>2025年3月1日 0:00 全球算力同步释放</strong></p><hr/><h3 style=\"text-align: start; line-height: 1.5;\"><strong>三大特权礼遇 仅限创始客户专享</strong></h3><h4 style=\"text-align: start;\">🚀 <strong>特权一：神经算力开荒礼</strong></h4><p style=\"text-align: start;\">✅ <strong>NeuroWAN基础版首年</strong><img src=\"https://ai-cloud-system.tos-cn-beijing.volces.com/2025/03/26/f8cf3556f11a4a7ea2da95e28cfd8473.jpg\" alt=\"\" data-href=\"\" style=\"width: 898.19px;height: 598.78px;\"><strong>1折</strong><br>▸ 原价￥1,800,000/年 → <strong>创始价￥180,000</strong><br>▸ 加赠价值￥500,000的<strong>AGI-Turbo加速包</strong>（全球任意5条跨国链路免费用）</p><h4 style=\"text-align: start;\">🔒 <strong>特权二：零信任安全护航</strong></h4><p style=\"text-align: start;\">✅ <strong>AGI-ZTM移动安全系统买3年送2年</strong><br>▸ 5年长效护航仅收3年费用，企业人均成本低至**￥9.9/人/月**<br>▸ 前20名签约客户赠送<strong>量子密钥管理模块</strong>（军工级防护）</p><h4 style=\"text-align: start;\">🌐 <strong>特权三：云端神经枢纽</strong></h4><p style=\"text-align: start;\">✅ <strong>AGI-Connect多云互联专线首单立减60%</strong><br>▸ 打通AWS/Azure/阿里云大模型算力池，传输成本**￥0.08/GB**（市场均价3折）<br>▸ 签约即送<strong>百万级联邦学习算力券</strong></p>', 0.00, 2, 'admin', 1, '2025-02-24 17:18:35', '瑞斯拜', 4, '2025-04-02 18:26:35', 0);
INSERT INTO `sys_active_center` (`id`, `name`, `start_date`, `end_date`, `picture`, `details`, `target_amount`, `status`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`) VALUES (7, ',kasndkans,d', '2025-08-18', '2025-08-30', 'https://ai-cloud-system.tos-cn-beijing.volces.com/2025/08/01/8dd55b64006548c5b2434da9da29fea2.png', '<h3 style=\"text-align: start; line-height: 1.5;\"><strong>逸雲数智试营业全球首发</strong></h3><p style=\"text-align: start;\"><strong>「数智无界 未来加速」—— AGI智算基座限时抢购计划</strong><br><strong>2025年4月1日 0:00 全球算力同步释放</strong></p><hr/><h3 style=\"text-align: start; line-height: 1.5;\"><strong>三大特权礼遇 仅限创始客户专享</strong></h3><h4 style=\"text-align: start;\">🚀 <strong>特权：神经算力开荒礼</strong></h4><p style=\"text-align: start;\"><br></p>', 1.00, 3, '瑞斯拜', 4, '2025-08-01 16:14:57', '瑞斯拜', 4, '2025-08-01 16:14:57', 0);
