INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (175, 53, '你能回复我  ', '当然可以啦，今天过得怎么样呢？', NULL, 1848278449937059867, '2025-02-14 19:03:39', NULL, 1848278449937059867, '2025-02-14 19:03:39', 0, 2);
