INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (219, 62, '逸云数智AI是你什么', '我就是逸云数智AI，是由逸云数智开发的人工智能助手，可以回答各种各样的问题，很高兴为你解答疑惑！', NULL, 1848278449937059867, '2025-02-24 16:30:33', NULL, 1848278449937059867, '2025-02-24 16:30:33', 0, 2);
INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (220, 62, '', '不太清楚你想要交流什么呢？你可以给我一个话题，比如问一个知识类的问题、分享一件有趣的事情或者寻求某种建议呀。', NULL, 1848278449937059867, '2025-02-24 16:31:21', NULL, 1848278449937059867, '2025-02-24 16:31:21', 0, 2);
INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (221, 62, '', '不太清楚你想要交流什么呢？你可以给我一个话题，比如问个问题、分享有趣的事情，或者是寻求建议呀。', NULL, 1848278449937059867, '2025-02-24 16:31:23', NULL, 1848278449937059867, '2025-02-24 16:31:23', 0, 2);
INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (222, 62, '你能陪我聊聊天嘛，豆包', '我不是豆包，我是逸云数智AI。不过我很乐意陪你聊天呢，今天过得怎么样呀？', NULL, 1848278449937059867, '2025-02-24 16:32:42', NULL, 1848278449937059867, '2025-02-24 16:32:42', 0, 2);
INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (223, 62, '很好', '很开心能得到你的认可呢！如果有任何问题都可以随时告诉我哦，无论是有趣的话题、生活中的困扰，还是知识问答。', NULL, 1848278449937059867, '2025-02-24 16:32:47', NULL, 1848278449937059867, '2025-02-24 16:32:47', 0, 2);
INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (224, 62, '如果对一个女生表白', '以下是一些向女生表白的建议和方式：\n\n### 一、准备工作\n1. **了解她的心意**\n   - 在表白之前，尽量确定她对你也有一定的好感。可以从日常相处中的细节判断，比如她是否愿意单独和你相处、是否对你的生活感兴趣、是否经常主动找你聊天等。\n2. **选择合适的时间和地点**\n   - **时间**\n     - 避免在她非常忙碌或者压力很大的时候表白。例如，不要在她临近重要考试、工作项目交付期限的时候表白。一个相对轻松的节假日，如周末或者小假期是比较好的选择。如果有特殊意义的日子，像她的生日或者你们相识的纪念日，也会让表白更具纪念性。\n   - **地点**\n     - 选择一个对你们有特殊意义的地方，比如你们第一次见面的地方、经常一起散步的公园等。或者是一个安静、舒适、浪漫的场所，如一家氛围温馨的西餐厅、海边等。\n\n### 二、表白方式\n1. **直接表白**\n   - 真诚地看着她的眼睛，说出你的心里话。例如：“[她的名字]，我喜欢你很久了。从我们第一次见面，你[描述一个当时让你心动的细节]，我就觉得你很特别。和你相处的每一刻我都很开心，我想让你知道，我希望能和你在一起，不仅仅是朋友，而是恋人。”\n2. **书信表白**\n   - 如果你觉得当面直接说会紧张，写一封信也是很浪漫的方式。信纸可以选择有质感的，字迹要工整（如果字不好看可以用漂亮的字体打印）。在信中表达你对她的感情，例如：“亲爱的[她的名字]，当我提起笔，满脑子都是你。我们一起度过的时光就像一部美好的电影在我脑海里不断放映。我发现自己越来越喜欢你，你的笑容、你的善良、你的小脾气，都让我着迷。我想和你分享生活中的喜怒哀乐，你愿意做我的女朋友吗？”\n3. **借助礼物表白**\n   - 送她一份有特殊意义的礼物，同时附上表白的话语。如果她喜欢读书，可以送一本有深度的爱情小说，并在书中夹一张纸条，写上：“就像书中的爱情一样，我希望我们也能有一段美好的故事。[她的名字]，我喜欢你。”如果是送首饰，可以说：“这个[首饰名字]就像我对你的感情，希望能一直陪伴在你身边，因为你是我心中最特别的人，我喜欢你。”\n\n### 三、表白时的态度\n1. **真诚**\n   - 真诚是最重要的，不要夸大其词或者伪装自己。真实地表达你的感受和想法，让她感受到你的真心。\n2. **自信**\n   - 保持自信的态度，但不要过于自负。相信自己的感情是有价值的，也要尊重她的决定，不管结果如何，都要坦然面对。\n3. **尊重她的反应**\n   - 如果她需要时间考虑，不要逼迫她马上答复；如果她拒绝了，也要礼貌地接受，不要死缠烂打，并且感谢她对你的坦诚。', NULL, 1848278449937059867, '2025-02-24 17:22:28', NULL, 1848278449937059867, '2025-02-24 17:22:28', 0, 2);
INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (225, 62, 'deepseek是什么', 'DeepSeek是一家人工智能相关的公司或组织。\n\n他们在人工智能技术研发等方面开展工作，例如可能涉及开发语言模型等人工智能技术成果，在自然语言处理等领域不断探索并推动相关技术的发展进步。', NULL, 1848278449937059867, '2025-02-24 17:43:29', NULL, 1848278449937059867, '2025-02-24 17:43:29', 0, 2);
INSERT INTO `sys_ai_dialogue_msg` (`id`, `dialogue_id`, `user_value`, `ai_value`, `create_by`, `create_by_id`, `create_time`, `update_by`, `update_by_id`, `update_time`, `del_flag`, `status`) VALUES (226, 62, '你有deepseek嘛', '我是逸云数智AI，和DeepSeek没有关系。我是由逸云数智独立开发的人工智能，可以回答各种各样的问题，包括科学知识、生活常识、文化历史等。', NULL, 1848278449937059867, '2025-02-24 17:43:36', NULL, 1848278449937059867, '2025-02-24 17:43:36', 0, 2);
