                                     `update_by_id` bigint DEFAULT NULL,
                                     `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                     `del_flag` tinyint DEFAULT '0',
                                     PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='活动管理';

