DROP TABLE IF EXISTS `sys_apply`;
CREATE TABLE `sys_apply` (
                             `id` bigint NOT NULL AUTO_INCREMENT,
                             `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '应用名称',
                             `intro` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用简介',
                             `type_id` bigint NOT NULL DEFAULT '0' COMMENT '分类id',
                             `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用标签',
                             `publish_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发布者名称',
                             `publish_user_avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发布者头像',
                             `version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用版本',
                             `mirror_size` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像大小',
                             `introduce` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '应用介绍',
                             `sort` int NOT NULL COMMENT '序号',
                             `status` int NOT NULL DEFAULT '0' COMMENT '状态',
                             `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                             `img` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图片地址',
                             `create_by_id` bigint DEFAULT NULL,
                             `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                             `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                             `update_by_id` bigint DEFAULT NULL,
                             `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                             `del_flag` tinyint DEFAULT '0',
                             `mirror_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像类型',
                             `mirror_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像版本',
                             `mirror_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像ID',
                             PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='应用';

