-- ----------------------------
-- Table structure for sys_contract
-- ----------------------------
DROP TABLE IF EXISTS `sys_contract`;
CREATE TABLE `sys_contract` (
                                `id` bigint NOT NULL AUTO_INCREMENT,
                                `user_id` bigint DEFAULT NULL COMMENT '用户id',
                                `contract_no` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '合同编号',
                                `complete_time` datetime DEFAULT NULL COMMENT '完成时间',
                                `link_order_no` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联订单号',
                                `status` int NOT NULL DEFAULT '1' COMMENT '状态 (1 草稿, 2 待签署，3 已签署， 3 已过期)',
                                `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
                                `client_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '甲方名称',
                                `client_contact_person` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '甲方联系人',
                                `client_contact_phone` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '甲方联系电话',
                                `client_contact_address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '甲方联系地址',
                                `file_download_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '下载文件地址',
                                `sign_flow_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'sign_flow_id',
                                `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                                `create_by_id` bigint DEFAULT NULL,
                                `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                                `update_by_id` bigint DEFAULT NULL,
                                `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                `del_flag` tinyint DEFAULT '0',
                                `file_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '填充后生成的文件ID',
                                `sign_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
                                `download_time` datetime DEFAULT NULL COMMENT '最后下载时间',
                                `type` int NOT NULL DEFAULT '1' COMMENT '合同类型（1 线上 2 线下）',
                                `upload_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '签署扫描件',
                                `verify_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核备注',
                                `user_type` int DEFAULT NULL COMMENT '用户类型（1 个人  2 企业）',
                                `sign_upload_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '已签署扫描件',
                                PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='合同管理';

-- ----------------------------
-- Records of sys_contract
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_coupon
-- ----------------------------
DROP TABLE IF EXISTS `sys_coupon`;
CREATE TABLE `sys_coupon` (
                              `id` int unsigned NOT NULL AUTO_INCREMENT,
                              `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_cs_0900_ai_ci NOT NULL COMMENT '优惠卷名称',
                              `type` int DEFAULT NULL COMMENT '优惠卷类型',
                              `threshold_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '满足金额',
                              `deduction_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '抵扣金额',
                              `receive_num` int NOT NULL DEFAULT '1' COMMENT '领取次数',
                              `receive_time_start` datetime DEFAULT NULL COMMENT '领取开始时间',
                              `receive_time_end` datetime DEFAULT NULL COMMENT '领取结束时间',
                              `use_time_start` datetime DEFAULT NULL COMMENT '使用开始时间',
                              `use_time_end` datetime DEFAULT NULL COMMENT '使用截至时间',
                              `receive_type` tinyint DEFAULT '2' COMMENT '领取条件，1 无条件，2 新人',
                              `count` int DEFAULT NULL COMMENT '优惠卷数量',
                              `range_type` int DEFAULT '1' COMMENT '范围类型 枚举定义',
                              `status` int DEFAULT '1' COMMENT '1上架 0下架',
                              `sort` int DEFAULT '0' COMMENT '排序',
                              `coupon_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_cs_0900_ai_ci DEFAULT NULL,
                              `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                              `create_by_id` bigint DEFAULT NULL,
                              `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                              `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                              `update_by_id` bigint DEFAULT NULL,
                              `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                              `del_flag` tinyint DEFAULT '0',
                              PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='优惠券';

-- ----------------------------
-- Records of sys_coupon
-- ----------------------------
BEGIN;
COMMIT;

