-- ----------------------------
-- Table structure for sys_customer
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer`;
CREATE TABLE `sys_customer` (
                                `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
                                `account_id` bigint DEFAULT NULL COMMENT '账户id',
                                `account_key` varchar(256) DEFAULT NULL COMMENT '账号密钥key',
                                `account_secret` varchar(512) DEFAULT NULL COMMENT '账号密钥',
                                `customer_name` varchar(100) DEFAULT NULL COMMENT '客户名称',
                                `avatar` varchar(200) DEFAULT NULL COMMENT '客户头像',
                                `phone` varchar(256) DEFAULT NULL COMMENT '手机号',
                                `gender` tinyint(1) NOT NULL DEFAULT '2' COMMENT '性别',
                                `balance` decimal(10,2) DEFAULT '0.00' COMMENT '余额',
                                `union_id` varchar(64) DEFAULT NULL COMMENT '客户在微信开放平台的唯一身份标识,通过此字段企业可将外部联系人与公众号/小程序用户关联起来。',
                                `open_id` varchar(64) DEFAULT NULL COMMENT '客户的唯一标识',
                                `birthday` date DEFAULT NULL COMMENT '生日',
                                `password` varchar(256) DEFAULT NULL COMMENT '密码',
                                `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
                                `qq` varchar(50) DEFAULT NULL COMMENT 'QQ号',
                                `inviter_id` bigint DEFAULT NULL COMMENT '邀请人id',
                                `inviter_time` timestamp NULL DEFAULT NULL COMMENT '邀请时间',
                                `status` tinyint(1) DEFAULT '0' COMMENT '状态',
                                `remark` text COMMENT '简介',
                                `register_time` timestamp NULL DEFAULT NULL COMMENT '注册时间',
                                `create_by` varchar(255) DEFAULT NULL COMMENT '创建人',
                                `create_by_id` bigint DEFAULT NULL COMMENT '创建人id',
                                `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                `update_by` varchar(255) DEFAULT NULL COMMENT '更新人',
                                `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                `update_by_id` bigint DEFAULT NULL COMMENT '更新人id',
                                `del_flag` tinyint(1) DEFAULT '0' COMMENT '删除标识 0 有效 1 删除',
                                `type` int NOT NULL DEFAULT '1' COMMENT '身份类型（1 个人账号， 2 企业账号）',
                                `company_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业名称',
                                `company_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业统一社会信用代码',
                                `company_address` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业注册地址',
                                `company_img` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业营业执照',
                                `company_contact_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业联系人名称',
                                `company_contact_phone` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业联系人电话',
                                `company_status` int NOT NULL DEFAULT '1' COMMENT '企业审核状态（1 未提交， 2 审核中， 3 已通过，4 未通过）',
                                `company_verify_remark` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业审核备注',
                                `company_verify_time` datetime DEFAULT NULL COMMENT '企业审核时间',
                                `cert_status` tinyint DEFAULT '1' COMMENT '认证状态（1未认证 2认证中 3已认证 4认证失败）',
                                `cert_type` tinyint DEFAULT NULL COMMENT '认证类型（1个人认证 2企业认证）',
                                `cert_time` datetime DEFAULT NULL COMMENT '认证时间',
                                `department_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '飞连的部门id',
                                PRIMARY KEY (`id`),
                                UNIQUE KEY `index_accountId` (`account_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1848278449937059875 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='客户表';

-- ----------------------------
-- Records of sys_customer
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_customer_amount_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_amount_log`;
CREATE TABLE `sys_customer_amount_log` (
                                           `id` bigint unsigned NOT NULL AUTO_INCREMENT,
                                           `order_id` bigint DEFAULT NULL COMMENT '订单id',
                                           `order_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单号',
                                           `customer_id` bigint DEFAULT NULL COMMENT '客户id',
                                           `amount_type` tinyint DEFAULT NULL COMMENT '金额类型，余额/代金卷',
                                           `transaction_type` tinyint DEFAULT NULL COMMENT '交易类型',
                                           `before_amount` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '0.000000' COMMENT '之前金额',
                                           `amount` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '0.000000' COMMENT '操作金额',
                                           `after_amount` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '0.000000' COMMENT '操作后金额',
                                           `create_time` timestamp NULL DEFAULT NULL COMMENT '操作时间',
                                           PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=263556 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户金额变更日志';

-- ----------------------------
-- Records of sys_customer_amount_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_customer_bill
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_bill`;
CREATE TABLE `sys_customer_bill` (
                                     `id` bigint unsigned NOT NULL AUTO_INCREMENT,
                                     `customer_id` bigint DEFAULT NULL COMMENT '客户ID',
                                     `bill` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账期',
                                     `bill_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账单号',
                                     `bill_date` date DEFAULT NULL COMMENT '账期时间',
                                     `source_type` tinyint DEFAULT NULL COMMENT '资源类型',
                                     `source_id` bigint unsigned DEFAULT NULL COMMENT '资源ID',
                                     `charge_type` tinyint DEFAULT NULL COMMENT '计费方式',
                                     `duration` int unsigned DEFAULT NULL COMMENT '使用时长',
                                     `charge_unit` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '计费单位',
                                     `bill_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账单类型',
                                     `settle_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '结算类型',
                                     `instance_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '实例ID',
                                     `instance_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '实例名称',
                                     `unit_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '计费单元',
                                     `region` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '地域',
                                     `zone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '可用区',
                                     `price_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '单价价格类型',
                                     `price` decimal(20,8) DEFAULT NULL COMMENT '单价',
                                     `usage` decimal(20,8) DEFAULT NULL COMMENT '用量',
                                     `usage_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用量单位',
                                     `original_price` varchar(32) COLLATE utf8mb4_general_ci DEFAULT '0.00000000' COMMENT '原价',
                                     `premium_price` decimal(20,8) DEFAULT NULL COMMENT '溢价价格',
                                     `user_discount_amount` decimal(20,8) DEFAULT NULL COMMENT '用户折扣金额',
                                     `pay_price` decimal(20,2) DEFAULT NULL COMMENT '应付价格',
                                     `voucher_amount` decimal(20,8) DEFAULT NULL COMMENT '代金券金额',
                                     `credit_line_amount` decimal(20,2) DEFAULT NULL COMMENT '授信额金额',
                                     `balance_pay_amount` decimal(20,8) DEFAULT '0.00000000' COMMENT '余额支付金额',
                                     `arrears_amount` decimal(20,2) DEFAULT '0.00' COMMENT '欠费金额',
                                     `pay_status` tinyint DEFAULT NULL COMMENT '支付状态',
                                     `pay_time` timestamp NULL DEFAULT NULL COMMENT '交易时间',
                                     `bill_start_time` timestamp NULL DEFAULT NULL COMMENT '账单开始时间',
                                     `bill_end_time` timestamp NULL DEFAULT NULL COMMENT '账单结束时间',
                                     `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                                     `create_by_id` bigint DEFAULT NULL COMMENT '创建人id',
                                     `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                     `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                                     `update_by_id` bigint DEFAULT NULL COMMENT '更新者id',
                                     `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                     `del_flag` tinyint DEFAULT '0',
                                     PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1996148975048200193 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户账单信息';

-- ----------------------------
-- Records of sys_customer_bill
-- ----------------------------
BEGIN;
COMMIT;

