-- ----------------------------
-- Table structure for sys_customer_bucket
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_bucket`;
CREATE TABLE `sys_customer_bucket` (
                                       `id` bigint NOT NULL AUTO_INCREMENT,
                                       `customer_id` bigint NOT NULL COMMENT '客户id',
                                       `name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '桶名称',
                                       `region` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '区域',
                                       `storage_type` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '存储类型（默认=标准存储）',
                                       `redundancy_type` tinyint DEFAULT NULL COMMENT '冗余类型（0单冗余 1多AZ冗余）',
                                       `bucket_strategy` tinyint DEFAULT NULL COMMENT '桶策略（0私有 1公共读 2公共读写）',
                                       `is_version` tinyint DEFAULT NULL COMMENT '是否开启版本控制（0不开启 1开启）',
                                       `create_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
                                       `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
                                       PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='对象存储桶';

-- ----------------------------
-- Records of sys_customer_bucket
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_customer_cert_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_cert_log`;
CREATE TABLE `sys_customer_cert_log` (
                                         `id` bigint NOT NULL AUTO_INCREMENT,
                                         `customer_id` bigint DEFAULT NULL COMMENT '客户id',
                                         `cert_type` tinyint DEFAULT NULL COMMENT '认证类型（1个人认证 2企业认证）',
                                         `company_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业名称',
                                         `company_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业统一社会信用代码',
                                         `company_address` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业注册地址',
                                         `company_img` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '企业营业执照',
                                         `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '名称（个人名称or法人名称）',
                                         `id_card` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '身份证号码（个人身份证号码or法人身份证号码）',
                                         `cert_status` tinyint DEFAULT '1' COMMENT '认证状态（1未认证 2认证中 3已认证 4认证失败）',
                                         `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                         `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                         PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='实名认证记录';

-- ----------------------------
-- Records of sys_customer_cert_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_customer_container
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_container`;
CREATE TABLE `sys_customer_container` (
                                          `id` bigint unsigned NOT NULL AUTO_INCREMENT,
                                          `order_id` bigint DEFAULT NULL COMMENT '订单id',
                                          `order_source_uid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单资源uid',
                                          `customer_id` bigint NOT NULL COMMENT '客户id',
                                          `cluster_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '集群id',
                                          `cluster_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '集群名称',
                                          `kubernetes_version` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'kubernetes版本号',
                                          `resource_public_access_default_enabled` tinyint DEFAULT NULL COMMENT '是否公网访问',
                                          `api_server_public_access_enabled` tinyint DEFAULT '0' COMMENT '是否API_Server公网访问',
                                          `node_pool_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '节点池id',
                                          `node_pool_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '节点池名称',
                                          `node_pool_number` int DEFAULT NULL COMMENT '节点池数量',
                                          `subnet_policy` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '多子网调度策略',
                                          `customer_instances_id` bigint DEFAULT NULL COMMENT '客户实例id',
                                          `customer_subnet_id` bigint DEFAULT NULL COMMENT '客户子网id',
                                          `is_open_security_hardening` tinyint DEFAULT '0' COMMENT '是否开启安全加固',
                                          `nat_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'nat网关id',
                                          `clb_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '负载均衡id',
                                          `status` tinyint DEFAULT NULL COMMENT '容器状态',
                                          `create_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
                                          `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
                                          PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户容器';

-- ----------------------------
-- Records of sys_customer_container
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_customer_coupon
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_coupon`;
CREATE TABLE `sys_customer_coupon` (
                                       `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
                                       `coupon_id` bigint DEFAULT NULL COMMENT '优惠卷id',
                                       `customer_id` bigint DEFAULT NULL COMMENT '客户id',
                                       `status` tinyint DEFAULT NULL COMMENT '状态， 1 已使用，0 未使用, 2 已失效',
                                       `create_time` timestamp NULL DEFAULT NULL COMMENT '获取时间/领取时间',
                                       `use_time_start` timestamp NULL DEFAULT NULL COMMENT '可使用开始时间',
                                       `use_time_end` timestamp NULL DEFAULT NULL COMMENT '可使用结束时间',
                                       PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户优惠卷';

