-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_create_image_log`;
CREATE TABLE `sys_customer_create_image_log` (
                                                 `id` bigint unsigned NOT NULL AUTO_INCREMENT,
                                                 `customer_id` bigint NOT NULL COMMENT '客户id',
                                                 `image_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像id',
                                                 `image_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像名称',
                                                 `create_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
                                                 `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
                                                 PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户自定义镜像创建记录表';

