-- ----------------------------
-- Table structure for sys_customer_credit_line
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_credit_line`;
CREATE TABLE `sys_customer_credit_line` (
                                            `id` int unsigned NOT NULL AUTO_INCREMENT,
                                            `customer_id` bigint DEFAULT NULL COMMENT '客户id',
                                            `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '总金额',
                                            `use_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '已使用金额',
                                            `status` tinyint DEFAULT '0' COMMENT '状态，0 可使用，1 已到期',
                                            `use_time_start` datetime DEFAULT NULL COMMENT '使用开始时间',
                                            `use_time_end` datetime DEFAULT NULL COMMENT '使用截至时间',
                                            `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                                            `create_by_id` bigint DEFAULT NULL,
