-- ----------------------------
-- Table structure for sys_customer_instances
-- ----------------------------
DROP TABLE IF EXISTS `sys_customer_instances`;
CREATE TABLE `sys_customer_instances` (
                                          `id` int unsigned NOT NULL AUTO_INCREMENT,
                                          `order_id` bigint DEFAULT NULL COMMENT '订单id',
                                          `order_source_uid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单资源uid',
                                          `password` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '密码',
                                          `instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '实例id',
                                          `ecs_type` int DEFAULT NULL COMMENT 'ecs类型',
                                          `ecs_scale` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '规格',
                                          `cpu_number` int DEFAULT NULL COMMENT 'cpu数量',
                                          `memory_size` int DEFAULT NULL COMMENT '内存大小',
                                          `cpu_model` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'cpu型号',
                                          `gpu_model` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '显卡型号',
                                          `gpu_memory` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '显卡显存',
                                          `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '实列描述',
                                          `instance_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '实列名称',
                                          `host_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主机名称',
                                          `image_id` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像id',
                                          `command_agent` tinyint(1) DEFAULT NULL COMMENT '是否开启installRunCommandAgent',
                                          `customer_id` bigint NOT NULL COMMENT '客户id',
                                          `region` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '区域',
                                          `zone_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '可用区id',
                                          `charge_type` tinyint DEFAULT NULL COMMENT '计费类型',
                                          `status` tinyint DEFAULT NULL COMMENT '实列状态',
                                          `expire_time` timestamp NULL DEFAULT NULL COMMENT '到期时间',
                                          `duration` int DEFAULT NULL COMMENT '时长',
                                          `duration_unit` tinyint DEFAULT NULL COMMENT '时长单位',
                                          `product_type` tinyint DEFAULT NULL COMMENT '产品类型（1火山云引擎 2自建服务器）',
                                          `bandwidth` int DEFAULT '1' COMMENT '带宽(M) 数量',
                                          `create_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
                                          `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
                                          `start_time` datetime DEFAULT NULL COMMENT '启动时间（自建服务器使用）',
                                          `stop_time` datetime DEFAULT NULL COMMENT '停止时间（自建服务器使用）',
                                          PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=261 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户实列信息';

