-- ----------------------------
-- Table structure for sys_ecs
-- ----------------------------
DROP TABLE IF EXISTS `sys_ecs`;
CREATE TABLE `sys_ecs` (
                           `id` int unsigned NOT NULL AUTO_INCREMENT,
                           `product_type` tinyint DEFAULT NULL COMMENT '产品类型（1火山云引擎 2自建服务器）',
                           `ecs_type` int DEFAULT NULL COMMENT 'ecs类型',
                           `ecs_scale` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务器规格',
                           `cpu_number` int DEFAULT '2' COMMENT 'cpu数量',
                           `memory_size` int DEFAULT '8' COMMENT '内存大小',
                           `cpu_model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'cpu型号',
                           `gpu_model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'gpu型号',
                           `gpu_memory` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'gpu内存',
                           `ip_price` decimal(10,2) DEFAULT NULL COMMENT '公网费用（按量计费时才有）',
                           `hours_price` decimal(10,6) DEFAULT '0.000000' COMMENT '按量计费',
                           `month_price` decimal(10,2) DEFAULT '0.00' COMMENT '包年包月',
                           `one_year_price` decimal(10,2) DEFAULT '0.00' COMMENT '1年',
                           `two_year_price` decimal(10,2) DEFAULT '0.00' COMMENT '2年',
                           `three_year_price` decimal(10,2) DEFAULT '0.00' COMMENT '3年',
                           `regions_zones` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '可用区',
                           `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                           `create_by_id` bigint DEFAULT NULL,
                           `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                           `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                           `update_by_id` bigint DEFAULT NULL,
                           `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                           `del_flag` tinyint DEFAULT '0',
                           PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=667 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='云服务器';

-- ----------------------------
-- Records of sys_ecs
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_extend
-- ----------------------------
DROP TABLE IF EXISTS `sys_extend`;
CREATE TABLE `sys_extend` (
                              `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
                              `type` int DEFAULT NULL COMMENT '类型（1 推广大使， 2 普通用户）',
                              `level` int DEFAULT NULL COMMENT '等级（1 新用户，2 激活用户， 3 老用户）',
                              `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '真实姓名',
                              `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
                              `share_key` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分享key',
                              `user_id` bigint NOT NULL COMMENT '用户id',
                              `parent_user_id` bigint DEFAULT '0' COMMENT '上级用户id',
                              `link` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '推广链接',
                              `first_scale` decimal(10,2) DEFAULT NULL COMMENT '一级佣金比例',
                              `two_scale` decimal(10,2) DEFAULT NULL COMMENT '二级佣金比例',
                              `first_count` int DEFAULT '0' COMMENT '一级用户数量',
                              `two_count` int DEFAULT '0' COMMENT '二级用户数量',
                              `order_count` int DEFAULT '0' COMMENT '分佣订单数量',
                              `total_commission` decimal(10,2) DEFAULT '0.00' COMMENT '累计佣金',
                              `status` int DEFAULT '1' COMMENT '状态（1审核中，2通过，3不通过）',
                              `verify_remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '驳回理由',
                              `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                              `create_by_id` bigint DEFAULT NULL,
                              `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                              `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                              `update_by_id` bigint DEFAULT NULL,
                              `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                              `del_flag` tinyint DEFAULT '0',
                              `can_withdrawal_amount` decimal(10,2) DEFAULT '0.00' COMMENT '可提现金额',
                              `bank_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行卡真实姓名',
                              `id_card` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行卡身份证',
                              `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行卡开户地址',
                              `bank` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行卡开户银行',
                              `bank_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行卡银行账号',
                              `qr_code_link` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '推广小程序二维码',
                              PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='推广大师';

-- ----------------------------
-- Records of sys_extend
-- ----------------------------
BEGIN;
COMMIT;

