                            `name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '文件名称带文件类型的(xx.txt)',
                            `path` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '文件全路徑/文件夹全路径',
