                                     `billing_type` int NOT NULL COMMENT '开票类型',
                                     `invoice_type` int NOT NULL DEFAULT '0' COMMENT '发票类型',
                                     `invoice_title` varchar(254) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT '发票抬头',
                                     `number` varchar(254) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纳税人识别号',
