                                     `account` varchar(254) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '基本开户账户',
                                     `address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '企业注册地址',
                                     `contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '企业联系人',
                                     `phone_number` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '企业电话',
                                     `contact_phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人电话',
