COMMIT;

-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu` (
                            `id` bigint NOT NULL AUTO_INCREMENT COMMENT '菜单ID',
                            `menu_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '菜单名称',
                            `parent_id` bigint DEFAULT '0' COMMENT '父菜单ID',
                            `order_num` int DEFAULT '0' COMMENT '显示顺序',
                            `path` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '路由地址',
                            `component` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '组件路径',
                            `query` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '路由参数',
                            `is_frame` tinyint DEFAULT '1' COMMENT '是否为外链（0是 1否）',
                            `is_cache` tinyint DEFAULT '0' COMMENT '是否缓存（0缓存 1不缓存）',
                            `menu_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '菜单类型（M目录 C菜单 F按钮）',
                            `visible` tinyint DEFAULT '0' COMMENT '菜单状态（0显示 1隐藏）',
                            `status` tinyint DEFAULT '0' COMMENT '菜单状态（0正常 1停用）',
                            `perms` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '权限标识',
                            `icon` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '#' COMMENT '菜单图标',
                            `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                            `create_by_id` bigint DEFAULT NULL,
                            `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                            `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                            `update_by_id` bigint DEFAULT NULL,
                            `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                            `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '备注',
                            `del_flag` tinyint DEFAULT '0',
                            PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=77 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='菜单权限表';

-- ----------------------------
-- Records of sys_menu
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_message
-- ----------------------------
DROP TABLE IF EXISTS `sys_message`;
CREATE TABLE `sys_message` (
                               `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
                               `msg_type` int NOT NULL COMMENT '消息类型(1 收到客户表单， 2 收到客户购买表达， 3 推广申请， 4 发票申请，5 合同申请)',
                               `text` text COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息说明',
                               `status` int NOT NULL DEFAULT '1' COMMENT '状态（1 未读， 2 已读）',
                               `user_id` bigint DEFAULT NULL COMMENT '用户id',
                               `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                               `create_by_id` bigint DEFAULT NULL,
                               `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                               `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                               `update_by_id` bigint DEFAULT NULL,
                               `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                               `del_flag` tinyint DEFAULT '0',
                               PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='系统消息';

-- ----------------------------
-- Records of sys_message
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_module
-- ----------------------------
DROP TABLE IF EXISTS `sys_module`;
CREATE TABLE `sys_module` (
                              `id` bigint NOT NULL AUTO_INCREMENT,
                              `type` int NOT NULL COMMENT '类型（1 模型， 2 数据）',
                              `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '封面',
                              `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
                              `intro` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '简介',
                              `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '标签',
                              `publish_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发布者名称',
                              `publish_user_avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发布者头像',
                              `introduce` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '介绍',
                              `sort` int NOT NULL COMMENT '序号',
                              `status` int NOT NULL DEFAULT '0' COMMENT '状态',
                              `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                              `create_by_id` bigint DEFAULT NULL,
                              `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                              `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                              `update_by_id` bigint DEFAULT NULL,
                              `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                              `del_flag` tinyint DEFAULT '0',
                              `mirror_size` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像大小',
                              `mirror_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像类型',
                              `mirror_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像版本',
                              `mirror_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '镜像ID',
                              PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='模型和数据';

-- ----------------------------
-- Records of sys_module
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_network_form
-- ----------------------------
DROP TABLE IF EXISTS `sys_network_form`;
CREATE TABLE `sys_network_form` (
                                    `id` bigint NOT NULL AUTO_INCREMENT,
                                    `name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '表单名称',
                                    `json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'json',
                                    `status` int DEFAULT '1' COMMENT '状态 1启用 2关闭',
                                    `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                                    `create_by_id` bigint DEFAULT NULL COMMENT '创建人id',
                                    `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                    `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                                    `update_by_id` bigint DEFAULT NULL COMMENT '更新者id',
                                    `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                    `del_flag` tinyint DEFAULT '0',
                                    `form_type` int NOT NULL DEFAULT '1' COMMENT '表单类型（1 咨询表单 2 购买表单）',
                                    PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='网络表单';

-- ----------------------------
-- Records of sys_network_form
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_network_product
-- ----------------------------
DROP TABLE IF EXISTS `sys_network_product`;
CREATE TABLE `sys_network_product` (
                                       `id` bigint NOT NULL AUTO_INCREMENT,
                                       `name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品名称',
                                       `memo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '产品描述',
                                       `refer_price` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '参考价',
                                       `image` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图片',
                                       `form_id` bigint DEFAULT NULL COMMENT '咨询表单id',
                                       `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '详情',
                                       `sort` int DEFAULT NULL COMMENT '序号',
                                       `status` int DEFAULT '1' COMMENT '状态 1启用 2关闭',
                                       `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                                       `create_by_id` bigint DEFAULT NULL COMMENT '创建人id',
                                       `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                       `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                                       `update_by_id` bigint DEFAULT NULL COMMENT '更新者id',
                                       `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                       `del_flag` tinyint DEFAULT '0',
                                       `pay_price` decimal(10,2) DEFAULT NULL COMMENT '售价',
                                       `crossed_price` decimal(10,2) DEFAULT NULL COMMENT '划线价',
                                       `pay_form_id` bigint DEFAULT NULL COMMENT '支付表单id',
                                       `bandwidth` int DEFAULT '2' COMMENT '带宽(M) （1 需要， 2 不需要）',
                                       `account_price` decimal(10,2) DEFAULT NULL COMMENT '账户单价',
                                       `bandwidth_price` decimal(10,2) DEFAULT NULL COMMENT '带宽单价',
                                       `ip_price` decimal(10,2) DEFAULT NULL COMMENT 'IP单价',
                                       `one_month_discount` int DEFAULT '100' COMMENT '1个月折扣（%）',
                                       `two_month_discount` int DEFAULT NULL COMMENT '2个月折扣（%）',
                                       `three_month_discount` int DEFAULT NULL COMMENT '3个月折扣（%）',
                                       `four_month_discount` int DEFAULT NULL COMMENT '4个月折扣（%）',
                                       `five_month_discount` int DEFAULT NULL COMMENT '5个月折扣（%）',
                                       `six_month_discount` int DEFAULT NULL COMMENT '6个月折扣（%）',
                                       `seven_month_discount` int DEFAULT NULL COMMENT '7个月折扣（%）',
                                       `eight_month_discount` int DEFAULT NULL COMMENT '8个月折扣（%）',
                                       `nine_month_discount` int DEFAULT NULL COMMENT '9个月折扣（%）',
                                       `ten_month_discount` int DEFAULT NULL COMMENT '10个月折扣（%）',
                                       `eleven_month_discount` int DEFAULT NULL COMMENT '11个月折扣（%）',
                                       `one_year_discount` int DEFAULT NULL COMMENT '1年折扣（%）',
                                       `two_year_discount` int DEFAULT NULL COMMENT '2年折扣（%）',
                                       `three_year_discount` int DEFAULT NULL COMMENT '3年折扣（%）',
                                       `is_account_ip_binding` tinyint DEFAULT '0' COMMENT '账户、IP是否绑定(0否 1是)',
                                       `is_ip_display` tinyint DEFAULT '1' COMMENT '是否显示IP(0否 1显示)',
                                       `is_bandwidth_display` tinyint DEFAULT '1' COMMENT '是否显示带宽(0否 1显示)',
                                       `is_ip_count_display` tinyint DEFAULT '0' COMMENT '是否显示IP个数（对应划线价字段）',
                                       `country` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '国家地区',
                                       `department_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '飞连的部门id',
                                       PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='网络产品';

-- ----------------------------
-- Records of sys_network_product
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_network_product_ip
-- ----------------------------
DROP TABLE IF EXISTS `sys_network_product_ip`;
CREATE TABLE `sys_network_product_ip` (
                                          `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
                                          `product_id` bigint DEFAULT NULL COMMENT 'AGI-C产品id',
                                          `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'IP地址',
                                          `public_ip` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '公网IP',
                                          `ip_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'IP地区',
                                          `user_id` bigint DEFAULT NULL COMMENT '用户id',
                                          `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '使用的飞连用户账户',
                                          `status` tinyint DEFAULT '0' COMMENT '使用状态（0未使用 1已使用）',
                                          `use_time` datetime DEFAULT NULL COMMENT '启用时间',
                                          `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                          `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                          PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AGI-C产品IP库';

-- ----------------------------
-- Records of sys_network_product_ip
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_network_value
-- ----------------------------
DROP TABLE IF EXISTS `sys_network_value`;
CREATE TABLE `sys_network_value` (
                                     `id` bigint NOT NULL AUTO_INCREMENT,
                                     `product_id` bigint DEFAULT NULL COMMENT '产品id',
                                     `form_id` bigint DEFAULT NULL COMMENT '表单id',
                                     `user_id` bigint DEFAULT NULL COMMENT '用户id',
                                     `product_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '产品名称',
                                     `form_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '表单名称',
                                     `json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '填写的json',
                                     `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                                     `create_by_id` bigint DEFAULT NULL COMMENT '创建人id',
                                     `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                     `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                                     `update_by_id` bigint DEFAULT NULL COMMENT '更新者id',
                                     `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                     `del_flag` tinyint DEFAULT '0',
                                     `form_type` int NOT NULL DEFAULT '1' COMMENT '表单类型（1 咨询表单 2 购买表单）',
                                     `bandwidth` int DEFAULT '1' COMMENT '带宽(M) 数量',
                                     `network_day` int DEFAULT '1' COMMENT '产品天数',
                                     `network_count` int DEFAULT '1' COMMENT '购买产品数量',
                                     `ip_count` int DEFAULT NULL COMMENT '购买IP数量',
                                     `actual_status` int DEFAULT '1' COMMENT '产品状态（1 未开通， 2 已开通， 3 已过期，4已停线，5已撤线）',
                                     `actual_agi_open_time` datetime DEFAULT NULL COMMENT '实际产品开通时间',
                                     `actual_agi_expire_time` datetime DEFAULT NULL COMMENT '产品到期时间',
                                     `pay_status` int DEFAULT NULL COMMENT '支付状态（0 未支付， 1 已支付）',
                                     `original_amount` decimal(10,2) DEFAULT NULL COMMENT '原價',
                                     `pay_amount` decimal(10,2) DEFAULT NULL COMMENT '實付價',
                                     `unit_price` decimal(10,2) DEFAULT NULL COMMENT '单价',
                                     `userpwd` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '账号和密码',
                                     `userpwd_list` json DEFAULT NULL COMMENT '账密ip集合',
                                     `charge_type` tinyint(1) DEFAULT NULL COMMENT '计费类型：按量计费（后付费），包年包月（先付费）',
                                     `duration` int DEFAULT NULL COMMENT '时长',
                                     `duration_unit` tinyint(1) DEFAULT NULL COMMENT '时长单位， 按量计费 小时/GB， 包年 年， 包月 月',
                                     `mobile` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系方式',
                                     `email` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '联系邮箱',
                                     `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
                                     `agi_customer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户名称（购买产品时补充字段）',
                                     `is_auto_renew` tinyint DEFAULT '0' COMMENT '是否自动续费（0否 1是）',
                                     `ip_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'IP地区',
                                     `department_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '飞连的部门id',
                                     `expire_status` tinyint DEFAULT '8' COMMENT '到期状态（0：1天内到期、 1：1天到期、 2：2天到期、 3：3天到期、4：4天到期、 5：5天到期、 6：6天到期、 7：7天到期、8：大于7天）',
                                     PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=166 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='网络产品填写内容';

-- ----------------------------
-- Records of sys_network_value
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_news
-- ----------------------------
DROP TABLE IF EXISTS `sys_news`;
CREATE TABLE `sys_news` (
                            `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
                            `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
                            `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '图片',
                            `image_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图片w',
                            `content` longtext COLLATE utf8mb4_general_ci COMMENT '内容',
                            `sort` int NOT NULL COMMENT '序号',
                            `status` int NOT NULL COMMENT '状态',
                            `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                            `create_by_id` bigint DEFAULT NULL,
                            `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                            `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                            `update_by_id` bigint DEFAULT NULL,
                            `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                            `del_flag` tinyint DEFAULT '0',
                            `memo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '简介',
                            PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='新闻';

-- ----------------------------
-- Records of sys_news
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_order
-- ----------------------------
DROP TABLE IF EXISTS `sys_order`;
CREATE TABLE `sys_order` (
                             `id` bigint NOT NULL AUTO_INCREMENT,
                             `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '订单号',
                             `order_type` tinyint NOT NULL COMMENT '订单类型',
                             `original_price` decimal(10,2) DEFAULT NULL COMMENT '订单原价',
                             `premium_price` decimal(10,2) DEFAULT NULL COMMENT '溢价价格',
                             `user_discount_amount` decimal(10,2) DEFAULT NULL COMMENT '用户折扣金额',
                             `voucher_id` bigint DEFAULT NULL COMMENT '代金券id',
                             `voucher_amount` decimal(10,2) DEFAULT '0.00' COMMENT '代金券金额',
                             `coupon_id` bigint DEFAULT NULL COMMENT '优惠卷id',
                             `coupon_amount` decimal(10,2) DEFAULT '0.00' COMMENT '优惠卷金额',
                             `credit_line_id` bigint DEFAULT NULL COMMENT '授信额id',
                             `credit_line_amount` decimal(10,2) DEFAULT '0.00' COMMENT '授信额金额',
                             `final_pay_amount` decimal(10,2) DEFAULT '0.00' COMMENT '最终支付价格',
                             `balance_pay_amount` decimal(10,2) DEFAULT '0.00' COMMENT '余额支付金额',
                             `online_pay_amount` decimal(10,2) DEFAULT '0.00' COMMENT '在线支付金额',
                             `online_pay_type` tinyint DEFAULT NULL COMMENT '在线支付方式',
                             `online_pay_serial_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '在线支付流水号',
                             `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
                             `order_status` tinyint(1) DEFAULT '0' COMMENT '订单状态',
                             `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                             `create_by_id` bigint DEFAULT NULL COMMENT '创建人id',
                             `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                             `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                             `update_by_id` bigint DEFAULT NULL COMMENT '更新者id',
                             `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                             `del_flag` tinyint DEFAULT '0',
                             `rewards_type` int DEFAULT NULL COMMENT '奖励类型 1充值奖励',
                             `recharge_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '充值活动名称',
                             `recharge_id` bigint DEFAULT NULL COMMENT '充值活动id',
                             `rewards_amount` decimal(10,2) DEFAULT NULL COMMENT '充值奖励金额',
                             `rewards_time` datetime DEFAULT NULL COMMENT '奖励时间',
                             `first_user_id` bigint DEFAULT NULL COMMENT '一级用户id',
                             `two_user_id` bigint DEFAULT NULL COMMENT '二级用户id',
                             `first_rate` decimal(10,2) DEFAULT NULL COMMENT '一级佣金比例',
                             `two_rate` decimal(10,2) DEFAULT NULL COMMENT '二级佣金比例',
                             `first_user_commission` decimal(10,2) DEFAULT NULL COMMENT '一级用户佣金',
                             `two_user_commission` decimal(10,2) DEFAULT NULL COMMENT '二级用户佣金',
                             `network_product_id` bigint DEFAULT NULL COMMENT '网络产品id',
                             `actual_agi_open_time` datetime DEFAULT NULL COMMENT '实际产品开通时间',
                             `network_value_id` bigint DEFAULT NULL COMMENT '购买订单表单id',
                             `bandwidth` int DEFAULT '0' COMMENT '带宽(M) 数量',
                             `network_day` int DEFAULT '0' COMMENT '产品天数',
                             `network_count` int DEFAULT NULL COMMENT '购买产品数量',
                             `actual_agi_expire_time` datetime DEFAULT NULL COMMENT '产品到期时间',
                             `actual_status` int DEFAULT NULL COMMENT '产品状态（1 未开通， 2 已开通， 3 已过期）',
                             `settlement_status` int NOT NULL DEFAULT '1',
                             `email` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'AGIC升级产品的邮箱',
                             `ip_count` int DEFAULT NULL COMMENT 'AGIC升级产品的IP数量',
                             `network_count_all` int DEFAULT NULL COMMENT '记录当前用户购买产品总量',
                             `ip_count_all` int DEFAULT NULL COMMENT '记录当前用户AGIC升级产品的IP总量',
                             `bandwidth_all` int DEFAULT NULL COMMENT '记录当前用户带宽(M) 总量',
                             PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1988157182398566401 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='订单';

-- ----------------------------
-- Records of sys_order
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_order_source
-- ----------------------------
DROP TABLE IF EXISTS `sys_order_source`;
CREATE TABLE `sys_order_source` (
                                    `id` int unsigned NOT NULL AUTO_INCREMENT,
                                    `uid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'uid，区分多个服务器参数',
                                    `order_id` bigint DEFAULT NULL COMMENT '订单id',
                                    `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '订单号',
                                    `regions_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '地区id',
                                    `source_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '资源id',
                                    `source_type` tinyint(1) DEFAULT '0' COMMENT '资源类型',
                                    `source_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '资源名称',
                                    `ecs_type` int DEFAULT NULL COMMENT 'ecs类型',
                                    `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '产品名称',
                                    `product_type` tinyint DEFAULT NULL COMMENT '产品类型（1火山云引擎 2自建服务器）',
                                    `config_detail` json DEFAULT NULL COMMENT '配置详情',
                                    `charge_type` tinyint(1) DEFAULT NULL COMMENT '计费类型：按量计费（后付费），包年包月（先付费）',
                                    `duration` int DEFAULT NULL COMMENT '时长',
                                    `duration_unit` tinyint(1) DEFAULT NULL COMMENT '时长单位， 按量计费 小时/GB， 包年 年， 包月 月',
                                    `expires_time` timestamp NULL DEFAULT NULL COMMENT '到期时间',
                                    `number` int DEFAULT '1' COMMENT '数量',
                                    `unit_price` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '单价金额 火山价格',
                                    `premium_price` decimal(10,6) DEFAULT '0.000000' COMMENT '溢价价格 平台溢价价格，单价*溢价比例',
                                    `user_discount_amount` decimal(10,6) DEFAULT '0.000000' COMMENT '用户折扣金额：溢价价格*折扣比列',
                                    `voucher_discount_amount` decimal(10,6) DEFAULT NULL COMMENT '代金卷抵扣金额',
                                    `coupon_discount_amount` decimal(10,6) DEFAULT '0.000000' COMMENT '优惠卷抵扣金额',
                                    `final_unit_price` decimal(10,6) DEFAULT '0.000000' COMMENT '最终单价',
                                    `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                                    `create_by_id` bigint DEFAULT NULL,
                                    `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                    `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                                    `update_by_id` bigint DEFAULT NULL,
                                    `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                    `del_flag` tinyint DEFAULT '0',
                                    PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2519 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='订单资源';

-- ----------------------------
-- Records of sys_order_source
-- ----------------------------
BEGIN;
COMMIT;

