-- ----------------------------
-- Table structure for sys_remit
-- ----------------------------
DROP TABLE IF EXISTS `sys_remit`;
CREATE TABLE `sys_remit` (
                             `id` bigint NOT NULL AUTO_INCREMENT,
                             `user_id` bigint DEFAULT NULL,
                             `bank_type` int DEFAULT NULL COMMENT '银行类型（1 国内， 2 国外）',
                             `bank_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行名称',
                             `account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '开户名称',
                             `bank_no` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行卡号',
                             `swift_code` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'SWIFT CODE',
                             `amount` decimal(10,2) DEFAULT NULL COMMENT '打款金额',
                             `remit_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '汇款主体名',
                             `status` int DEFAULT '1' COMMENT '状态（1 待核实， 2 已打款， 3 未打款）',
                             `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核备注',
                             `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                             `create_by_id` bigint DEFAULT NULL,
                             `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                             `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                             `update_by_id` bigint DEFAULT NULL,
                             `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                             `del_flag` tinyint DEFAULT '0',
                             PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='对公打款';

-- ----------------------------
-- Records of sys_remit
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role` (
                            `id` bigint NOT NULL AUTO_INCREMENT COMMENT '角色ID',
                            `role_name` varchar(30) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '角色名称',
                            `admin` tinyint DEFAULT '0' COMMENT '是否为超管，1是，0否',
                            `role_sort` int NOT NULL DEFAULT '0' COMMENT '显示顺序',
                            `data_scope` tinyint DEFAULT '1' COMMENT '数据范围（1：全部数据权限 2：自定数据权限 3：本人数据权限 ）',
                            `menu_check_strictly` tinyint(1) DEFAULT '1' COMMENT '菜单树选择项是否关联显示',
                            `dept_check_strictly` tinyint(1) DEFAULT '1' COMMENT '部门树选择项是否关联显示',
                            `status` tinyint NOT NULL DEFAULT '0' COMMENT '角色状态（0正常 1停用）',
                            `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                            `create_by_id` bigint DEFAULT NULL COMMENT '创建者id',
                            `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                            `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                            `update_by_id` bigint DEFAULT NULL COMMENT '更新者id',
                            `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                            `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
                            `del_flag` tinyint DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
                            PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色信息表';

-- ----------------------------
-- Records of sys_role
-- ----------------------------
BEGIN;
COMMIT;

