-- ----------------------------
-- Table structure for sys_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user` (
                            `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
                            `user_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '用户账号',
                            `nick_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '用户昵称',
                            `phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '手机号码',
                            `sex` tinyint DEFAULT '0' COMMENT '用户性别（0男 1女 2未知）',
                            `avatar` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '头像地址',
                            `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '密码',
                            `role_id` bigint DEFAULT NULL COMMENT '角色id',
                            `status` tinyint DEFAULT '0' COMMENT '帐号状态（0正常 1停用,2离职）',
                            `entry_time` date DEFAULT NULL COMMENT '入职时间',
                            `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                            `create_by_id` bigint DEFAULT NULL COMMENT '创建人id',
                            `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                            `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                            `update_by_id` bigint DEFAULT NULL COMMENT '更新人id',
                            `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                            `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
                            `del_flag` tinyint DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
                            PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户信息表';

-- ----------------------------
-- Records of sys_user
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_volume
-- ----------------------------
DROP TABLE IF EXISTS `sys_volume`;
CREATE TABLE `sys_volume` (
                              `id` int unsigned NOT NULL AUTO_INCREMENT,
                              `kind` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '云盘属性， system 系统盘，data 数据盘',
                              `volume_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '云盘类型 essd',
                              `volume_scale` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '云盘规格',
                              `volume_capacity` int NOT NULL COMMENT '云盘容量',
                              `io_ps` int DEFAULT NULL COMMENT 'io_ps',
                              `io_ps_step_size` decimal(10,2) DEFAULT NULL COMMENT 'iops步长',
                              `throughput` decimal(10,2) DEFAULT NULL COMMENT '吞吐量',
                              `throughput_step_size` decimal(10,2) DEFAULT NULL COMMENT '吞吐量步长',
                              `hours_price` decimal(10,6) DEFAULT '0.000000' COMMENT '按量计费',
                              `month_price` decimal(10,2) DEFAULT '0.00' COMMENT '包年包月',
                              `one_year_price` decimal(10,2) DEFAULT '0.00' COMMENT '1年',
                              `two_year_price` decimal(10,2) DEFAULT '0.00' COMMENT '2年',
                              `three_year_price` decimal(10,2) DEFAULT '0.00' COMMENT '3年',
                              `regions_zones` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '可用区',
                              `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
                              `create_by_id` bigint DEFAULT NULL,
                              `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                              `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
                              `update_by_id` bigint DEFAULT NULL,
                              `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                              `del_flag` tinyint DEFAULT '0',
                              PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='云盘';

